CREATE TABLE IF NOT EXISTS root_missions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id TEXT, objective TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'READY', risk TEXT NOT NULL DEFAULT 'low', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS root_tasks (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), mission_id UUID REFERENCES root_missions(id) ON DELETE CASCADE, command TEXT NOT NULL, title TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'NOT_STARTED', risk TEXT NOT NULL DEFAULT 'low', human_gate BOOLEAN NOT NULL DEFAULT false, output JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS root_approvals (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), mission_id UUID REFERENCES root_missions(id) ON DELETE CASCADE, task_id UUID REFERENCES root_tasks(id) ON DELETE CASCADE, decision TEXT NOT NULL, actor_id TEXT, reason TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS root_verifications (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), mission_id UUID REFERENCES root_missions(id) ON DELETE CASCADE, task_id UUID REFERENCES root_tasks(id) ON DELETE CASCADE, status TEXT NOT NULL, evidence JSONB, limitations TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS root_memory (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id TEXT, category TEXT NOT NULL, content JSONB NOT NULL, confidence TEXT NOT NULL DEFAULT 'observed', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS root_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), mission_id UUID REFERENCES root_missions(id) ON DELETE CASCADE, event_type TEXT NOT NULL, payload JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
